class BlendModifierReferenceTest {
    private fun mesh(co: FloatArray, faces: Array<IntArray>, edges: IntArray, uv: FloatArray?, smooth: BooleanArray): BlendMeshData {
        val fStart = IntArray(faces.size)
        val fSize = IntArray(faces.size)
        var n = 0
        for (i in faces.indices) { fStart[i] = n; fSize[i] = faces[i].size; n += faces[i].size }
        val corners = IntArray(n)
        for (i in faces.indices) faces[i].copyInto(corners, fStart[i])
        val used = HashSet<Long>()
        for (f in faces) for (k in f.indices) used.add(BlendMeshData.key(f[k], f[(k + 1) % f.size]))
        val loose = ArrayList<Int>()
        for (e in 0 until edges.size / 2) if (BlendMeshData.key(edges[e * 2], edges[e * 2 + 1]) !in used) { loose.add(edges[e * 2]); loose.add(edges[e * 2 + 1]) }
        val d = BlendMeshData(co, fStart, fSize, corners, IntArray(faces.size), smooth, uv, null, null, emptyMap(), null, loose.toIntArray(), null, emptyList())
        d.fileEdges = edges
        return d
    }

    private fun assertSameVerts(expected: FloatArray, got: FloatArray, tol: Float = 1e-4f) {
        assertEquals(expected.size, got.size)
        fun check(a: FloatArray, b: FloatArray) {
            for (i in 0 until a.size / 3) {
                var best = Float.MAX_VALUE
                for (j in 0 until b.size / 3) {
                    var s = 0f
                    for (k in 0 until 3) { val x = a[i * 3 + k] - b[j * 3 + k]; s += x * x }
                    if (s < best) best = s
                }
                assertTrue("vertex $i off by ${sqrt(best)}", sqrt(best) <= tol)
            }
        }
        check(expected, got)
        check(got, expected)
    }
