    private fun cube(): BlendMeshData {
        val h = 0.5f
        val co = floatArrayOf(-h, -h, -h, -h, -h, h, -h, h, -h, -h, h, h, h, -h, -h, h, -h, h, h, h, -h, h, h, h)
        val faces = arrayOf(intArrayOf(0, 1, 3, 2), intArrayOf(2, 3, 7, 6), intArrayOf(6, 7, 5, 4), intArrayOf(4, 5, 1, 0), intArrayOf(2, 6, 4, 0), intArrayOf(7, 3, 1, 5))
        val edges = ArrayList<Int>()
        val seen = HashSet<Long>()
        for (f in faces) for (k in f.indices) { val a = f[k]; val b = f[(k + 1) % 4]; if (seen.add(BlendMeshData.key(a, b))) { edges.add(a); edges.add(b) } }
        return mesh(co, faces, edges.toIntArray(), null, BooleanArray(6))
    }

    @Test
    fun multiresZeroDisplacementEqualsSubsurf() {
        val gs = 3
        val zero = MultiresDisp(Array<FloatArray?>(24) { FloatArray(gs * gs * 3) }, gs)
        val plain = BlendMeshData.subsurf(cube(), 2, 4, true, false, true, BlendSubdiv.BOUNDARY_EDGE_ONLY, BlendSubdiv.FVAR_BOUNDARIES)
        val disp = BlendMeshData.subsurf(cube(), 2, 4, true, false, true, BlendSubdiv.BOUNDARY_EDGE_ONLY, BlendSubdiv.FVAR_BOUNDARIES, zero)
        assertEquals(plain.nV, disp.nV)
        assertSameVerts(plain.co, disp.co, 1e-6f)
    }

    @Test
    fun multiresNormalDisplacementMovesFaceCentersAlongNormal() {
        val gs = 3
        val grids = Array<FloatArray?>(24) { FloatArray(gs * gs * 3).also { g -> for (i in 0 until gs * gs) g[i * 3 + 2] = 0.1f } }
        val plain = BlendMeshData.subsurf(cube(), 1, 4, true, false, true, BlendSubdiv.BOUNDARY_EDGE_ONLY, BlendSubdiv.FVAR_BOUNDARIES)
        val disp = BlendMeshData.subsurf(cube(), 1, 4, true, false, true, BlendSubdiv.BOUNDARY_EDGE_ONLY, BlendSubdiv.FVAR_BOUNDARIES, MultiresDisp(grids, gs))
        var centers = 0
        for (v in 0 until plain.nV) {
            val x = plain.co[v * 3]; val y = plain.co[v * 3 + 1]; val z = plain.co[v * 3 + 2]
            val axis = (0 until 3).firstOrNull { k -> abs(abs(plain.co[v * 3 + k]) - maxOf(abs(x), abs(y), abs(z))) < 1e-6f && (0 until 3).all { j -> j == k || abs(plain.co[v * 3 + j]) < 1e-6f } } ?: continue
            centers++
            val delta = FloatArray(3) { disp.co[v * 3 + it] - plain.co[v * 3 + it] }
            assertEquals(0.1f, sqrt(delta[0] * delta[0] + delta[1] * delta[1] + delta[2] * delta[2]), 1e-5f)
            for (k in 0 until 3) if (k != axis) assertEquals(0f, delta[k], 1e-5f)
        }
        assertEquals(6, centers)
    }

