    fun allSmoothMeshUsesVertexNormalsAcrossNonManifoldFans() {
        val co = floatArrayOf(0f, 0f, 0f, 1f, 0f, 0f, 0f, 1f, 0f, -1f, 0f, 0f, 0f, -1f, 0.5f)
        val corners = intArrayOf(0, 1, 2, 0, 3, 4)
        val fStart = intArrayOf(0, 3)
        val fSize = intArrayOf(3, 3)
        val cn = BlendNormals.cornerNormals(co, corners, fStart, fSize, BooleanArray(2), null)
        val vn = MeshTopology(corners, fStart, fSize, IntArray(0)).vertexNormals(co)
        for (k in 0 until 3) { assertEquals(vn[k], cn[k], 1e-7f); assertEquals(vn[k], cn[9 + k], 1e-7f) }
    }

    private fun bevel(d: BlendMeshData, value: Float, seg: Int, flags: Int, profileType: Int, affect: Int, faceStr: Int, profile: BevelCurveProfile.Profile?): BlendMeshData =
        BlendBevelModifier.apply(d, value, seg, flags, 0, profileType, 1 shl 3, 0, -1, faceStr, 0, 0, 0, affect, 0.5f, 0.5235988f, 0.1f, "", "bevel_weight_edge", "bevel_weight_vert", 1, profile)

    private fun assertSameCornerNormals(expected: FloatArray, r: BlendMeshData) {
        val nn = BlendNormals.cornerNormals(r.co, r.corners, r.fStart, r.fSize, r.faceSmooth?.let { s -> BooleanArray(s.size) { !s[it] } }, r.normalSpec())
        val got = FloatArray(r.corners.size * 6)
        for (c in r.corners.indices) { val v = r.corners[c]; for (k in 0 until 3) { got[c * 6 + k] = r.co[v * 3 + k]; got[c * 6 + 3 + k] = nn[c * 3 + k] } }
        assertEquals(expected.size, got.size)
        fun check(a: FloatArray, b: FloatArray) {
            for (i in 0 until a.size / 6) {
                var best = Float.MAX_VALUE
                for (j in 0 until b.size / 6) {
                    var s = 0f
                    for (k in 0 until 6) { val x = a[i * 6 + k] - b[j * 6 + k]; s += x * x }
                    if (s < best) best = s
                }
                assertTrue("corner $i off by ${sqrt(best)}", sqrt(best) <= 1e-4f)
            }
        }
        check(expected, got)
        check(got, expected)
    }
