    @Test
    fun profileEdgeOrderingFollowsDarwinQsort() {
        fun sorted(n: Int): List<Int> { val a = IntArray(n) { it }; BevelCurveProfile.darwinQsort(a, n) { _, _ -> 1 }; return a.toList() }
        assertEquals(listOf(2, 7, 6, 5, 0, 4, 3, 1), sorted(8))
        assertEquals(listOf(3, 8, 0, 9, 4, 10, 6, 11, 2, 13, 7, 12, 1, 14, 5, 15), sorted(16))
        assertEquals(listOf(6, 50, 0, 51, 1, 52, 8, 53, 10, 54, 2, 55, 43, 59, 27, 91, 35, 67, 19, 83, 5, 99, 23, 63, 39, 71, 18, 79, 47, 87, 31, 95, 13, 57, 15, 61, 37, 65, 25, 69, 41, 73, 3, 77, 45, 81, 29, 85, 49, 89, 21, 93, 11, 97, 33, 56, 34, 58, 17, 60, 36, 62, 24, 64, 38, 66, 12, 68, 40, 70, 26, 72, 42, 74, 14, 76, 44, 78, 28, 80, 46, 82, 20, 84, 48, 86, 30, 88, 7, 90, 16, 92, 9, 94, 32, 96, 4, 98, 22, 75), sorted(100))
        val v = floatArrayOf(0.5f, 0f, 1f, 0f, 0f, 2f, 0f, 0.25f, 0f, 0f, 1f, 0f)
        val a = IntArray(12) { it }
        BevelCurveProfile.darwinQsort(a, 12) { x, y -> if (v[x] > v[y]) 0 else 1 }
        assertEquals(listOf(6, 2, 5, 0, 7, 10, 8, 4, 3, 11, 1, 9), a.toList())
    }

