        assertSameVerts(floatArrayOf(-0.50001f, -0.50001f, -0.50001f, 0.1f, 0.1f, 0.1f, -0.50001f, -0.50001f, 0.50001f, 0.1f, 0.1f, -0.1f, -0.50001f, 0.50001f, -0.50001f, 0.1f, -0.1f, 0.1f, -0.50001f, 0.50001f, 0.50001f, 0.1f, -0.1f, -0.1f, 0.50001f, -0.50001f, -0.50001f, -0.1f, 0.1f, 0.1f, 0.50001f, -0.50001f, 0.50001f, -0.1f, 0.1f, -0.1f, 0.50001f, 0.50001f, -0.50001f, -0.1f, -0.1f, 0.1f, 0.50001f, 0.50001f, 0.50001f, -0.1f, -0.1f, -0.1f), r.co)
    }

    @Test
    fun solidifyComplexFanFlatBoundary() {
        val d = mesh(floatArrayOf(0f, 0f, 0f, 1f, 0f, 0f, 0f, 1f, 0f, -1f, 0f, 0f, 0f, -1f, 0f, 0f, 0f, 1f), arrayOf(intArrayOf(0, 1, 5), intArrayOf(0, 2, 5), intArrayOf(0, 3, 5), intArrayOf(0, 4, 5)), intArrayOf(0, 5, 0, 1, 1, 5, 0, 2, 2, 5, 0, 3, 3, 5, 0, 4, 4, 5), null, booleanArrayOf(false, false, false, false))
        val p = BlendMeshOps.SolidifyParams(0.100000001f, -1f, 0f, 0f, 1, 0, 0, 1, 0f, 0f, 0f, null, -1, -1)
        val r = BlendSolidifyComplex.apply(d, p, 2, 2, 9.99999975e-05f, 0f)
        assertEquals(18, r.nF)
