        assertEquals(32, r.fileEdges!!.size / 2)
        assertSameVerts(floatArrayOf(-1e-05f, -0.1f, 0f, -0.1f, 1e-05f, 0f, 1e-05f, 0.1f, 0f, 0.1f, -1e-05f, 0f, 1f, 0.1f, 0f, 1f, -1e-05f, 0f, -0.1f, 1f, 0f, 1e-05f, 1f, 0f, -1f, -0.1f, 0f, -1f, 1e-05f, 0f, 0.1f, -1f, 0f, -1e-05f, -1f, 0f, -1e-05f, -0.1f, 0.89999f, 0.1f, -1e-05f, 0.89999f, 1e-05f, 0.1f, 0.89999f, -0.1f, 1e-05f, 0.89999f), r.co)
